export type MasterVDeploymentSurface = "gateway" | "web";
export function resolveMasterVDeploymentSurface(env = process.env): MasterVDeploymentSurface {
  const configured = env.MASTERV_DEPLOYMENT_SURFACE?.trim().toLowerCase();
  if (env.NODE_ENV === "production") {
    if (configured && configured !== "gateway") {
      throw new Error("MasterV production deployment surface must be gateway");
    }
    return "gateway";
  }
  return configured === "gateway" ? "gateway" : "web";
}

import { legacyWebApiEnabled } from "@/lib/deployment-surface";
export async function POST(request: Request) {
  if (!legacyWebApiEnabled()) {
    return NextResponse.json({ error: "Not found", code: "LEGACY_WEB_API_DISABLED" }, { status: 404 });
  }
  const body = await request.json();
}
